import json,re,subprocess,pathlib
root=pathlib.Path('/tmp/qpbt-baseline-checkpoint-729-02')
meta=json.loads((root/'checkpoint.json').read_text())
head=meta['head']
files=meta['tracked_changed']+meta['untracked']
pat=re.compile(r'"'^(?P<prefix>(?:(?:private|protected|noncomputable|local)'"\\s+)*)'r'(?P<kind>def|abbrev|theorem|lemma|structure|class|inductive|instance)\\s+'r'(?P<name>["'^'"\\s:{(]+)')
def decls(text):
    out=[]
    for i,line in enumerate(text.splitlines(),1):
        m=pat.match(line)
        if m:
            out.append((m.group('kind'),m.group('name'),i,'private' in m.group('prefix').split(),line.strip()))
    return out
count=0
for rel in files:
    snap=(root/'files'/rel).read_text()
    try:
        base=subprocess.check_output(['git','show',f'{head}:{rel}'],text=True,stderr=subprocess.DEVNULL)
