        base=''
    bkeys={(k,n) for k,n,*_ in decls(base)}
    new=[d for d in decls(snap) if (d[0],d[1]) not in bkeys]
    if new:
        print(f'## {rel}')
        for k,n,l,p,raw in new:
            print(f'{l}\\t{\"private\" if p else \"public\"}\\t{k}\\t{n}\\t{raw}')
            count+=1
print('TOTAL',count)
