import json,re,subprocess,pathlib
root=pathlib.Path('/tmp/qpbt-baseline-checkpoint-729-02'); head=json.loads((root/'checkpoint.json').read_text())['head']
files=json.loads((root/'checkpoint.json').read_text())['tracked_changed']+json.loads((root/'checkpoint.json').read_text())['untracked']
pat=re.compile(r'"'^(?P<prefix>(?:(?:private|protected|noncomputable|local)'"\\s+)*)'r'(?P<kind>def|abbrev|theorem|lemma|structure|class|inductive|instance)\\s+'r'(?P<name>["'^'"\\s:{(]+)')
def ds(text):
 lines=text.splitlines(); out=[]
 for i,line in enumerate(lines):
  m=pat.match(line)
  if m: out.append((m.group('kind'),m.group('name'),i+1))
 return out,lines
def doc(lines,idx):
 j=idx-2
 while j>=0 and not lines[j].strip(): j-=1
 if j>=0 and '-/' in lines[j]:
  e=j; depth=0
  while j>=0:
   if '/-' in lines[j]:
    s=j; break
   j-=1
  else:return ''
  txt=' '.join(x.strip(' /-*\\t') for x in lines[s:e+1])
  return re.sub(r'\\s+',' ',txt)[:500]
 return ''
def header(lines,idx):
 bits=[]
 for x in lines[idx-1:min(len(lines),idx+13)]:
  bits.append(x.strip())
  if ':= by' in x or x.endswith(':=') or x.endswith('where') or x.endswith(':= by'): break
 return re.sub(r'\\s+',' ',' '.join(bits))[:650]
for rel in files:
 text=(root/'files'/rel).read_text(); decl,lines=ds(text)
 try: base=subprocess.check_output(['git','show',f'{head}:{rel}'],text=True,stderr=subprocess.DEVNULL)
 except subprocess.CalledProcessError: base=''
 b={(k,n) for k,n,_ in ds(base)[0]}
 new=[x for x in decl if (x[0],x[1]) not in b]
 if not new: continue
 print('\\n## '+rel)
 for k,n,l in new:
  print(f'@{l} {k} {n}\\nDOC: {doc(lines,l)}\\nSIG: {header(lines,l)}')
PY"

