\begin{proof}
	\uses{lem:qld-4-10, lem:qld-4-10-same-placement, lem:qld-sublines,
		lem:qld-xz-lines, lem:overlap-gap-distance,
		lem:qld-sublines-uniform-point, def:line-point-dist}
